ST.xhtml:
R_TRIG[1](CLK:=collect_Old_Plate_Slot>0);
R_TRIG[2](CLK:=scrape_Old_Plate_Slot>0);
//机器人流程
IF MODE_State=1 THEN	
	IF R_TRIG[1].Q THEN
		收集瓶组站位符:=TRUE;
	END_IF
	IF R_TRIG[2].Q THEN
		收集器组站位符:=TRUE;
	END_IF

	CASE 机器人流程 OF
		0:
			IF Status=0 THEN
				IF 上样点样允许放硅胶板 THEN
					机器人流程:=10;
				ELSIF  上样点样允许取硅胶板 AND scrape_Step=0 AND NOT 刮板拍照工位站位符 THEN 
					机器人流程:=20;
				ELSIF 拍照工位允许取硅胶板去展开 AND (Expand_Step=0 OR Expand_Step=30) THEN
					机器人流程:=30;
				ELSIF 展开工位允许取硅胶板 AND scrape_Step=0 AND NOT 刮板拍照工位站位符 THEN       //刮板拍照空闲
					机器人流程:=40;
				ELSIF scrape_Fetch_Rack_Plate>0 AND NOT 刮板拍照暂存工位传感器 THEN 
					机器人流程:=70;
				ELSIF collect_Fetch_Rack_Plate>0 AND NOT 收集平台暂存工位传感器 THEN
					机器人流程:=60;
				ELSIF collect_Old_Plate_Slot>0 AND 收集平台暂存工位传感器 AND NOT 收集瓶组站位符  THEN
					机器人流程:=80;
				ELSIF scrape_Old_Plate_Slot>0 AND 刮板拍照暂存工位传感器 AND  NOT 收集器组站位符 THEN
					机器人流程:=90;
				ELSIF 拍照工位允许放收集器 AND 刮板拍照暂存工位传感器 AND scrape_Consume_Slot>0 THEN 
					机器人流程:=100;
				ELSIF 拍照工位允许取收集器 AND collect_Step=0 THEN           //收集工位空闲
					机器人流程:=110;
				ELSIF 收集工位允许放收集瓶 AND 收集平台暂存工位传感器 AND collect_Consume_Slot>0 THEN
					机器人流程:=120;
				ELSIF 收集工位允许取收集器 AND collect_Powder_Return_Slot>0 THEN
					机器人流程:=130;
				ELSIF 收集工位允许机器人取收集瓶放暂存工位 AND collect_Consume_Slot>0 THEN
					机器人流程:=140;
				ELSIF 拍照工位允许取硅胶板放废料区 THEN
					机器人流程:=50;
				END_IF
			END_IF



//	取升降机硅胶板放点样机构上

		10:                                                  
			ParameterList3:=1;                           //取1号吸盘工具
			A00_取放工具();
			IF 取工具完成 THEN
				取工具完成:=FALSE;
				ParameterList3:=0; 
				机器人流程:=11;
			END_IF
		11:
			A10_取升降机硅胶板();
			IF 取升降硅胶板完成 THEN
				取升降硅胶板完成:=FALSE;
				机器人流程:=12;		
			END_IF
		12:
			A15_放点样硅胶板();
			IF 放点样硅胶板完成 THEN
				FunctionID:=0;
				放点样硅胶板完成:=FALSE;
				机器人流程:=0;
			END_IF






//取点样硅胶板放拍照机构上
		20:
			ParameterList3:=1;                           //取1号吸盘工具
			A00_取放工具();
			IF 取工具完成 THEN
				取工具完成:=FALSE;
				机器人流程:=21;
			END_IF
		21:
			A20_取点样硅胶板();
			IF 取点样硅胶板完成 THEN

				机器人流程:=22;
			END_IF
		22:
			IF 拍照工位允许放硅胶板 THEN

				机器人流程:=23;
			END_IF
		23:
			A35_放拍照硅胶板();
			IF 放拍照硅胶板完成 THEN
				FunctionID:=0;
				放拍照硅胶板完成:=FALSE;
				机器人流程:=0;
			END_IF




//取拍照机构硅胶板放展缸
		30:
			ParameterList3:=1;                           //取1号吸盘工具
			A00_取放工具();
			IF 取工具完成 THEN
				取工具完成:=FALSE;
				机器人流程:=31;
			END_IF
		31:
			A32_取拍照硅胶板();
			IF 取拍照硅胶板完成 THEN

				机器人流程:=32;
			END_IF
		32:
			IF 展开工位允许放硅胶板1 THEN
				机器人流程:=33;
			END_IF
		33:
			A25_放展缸硅胶板();
			IF 展开工位机器人放硅胶板完成 THEN
				FunctionID:=0;
				机器人流程:=0;
			END_IF





//取展缸硅胶板到拍照刮取机构
		40:
			ParameterList3:=1;                           //取1号吸盘工具
			A00_取放工具();
			IF 取工具完成 THEN
				取工具完成:=FALSE;
				机器人流程:=41;
			END_IF
		41:
			A30_取展缸硅胶板();
			IF 取展缸硅胶板完成 THEN
				取展缸硅胶板完成:=FALSE;
				展开工位允许取硅胶板:=FALSE;
				机器人流程:=42;
			END_IF
		42:
			IF 拍照工位允许放硅胶板 THEN
				机器人流程:=43;
			END_IF
		43:
			A35_放拍照硅胶板();
			IF 放拍照硅胶板完成 THEN
				FunctionID:=0;
				放拍照硅胶板完成:=FALSE;
				机器人流程:=0;
			END_IF







//取拍照刮取硅胶板放到废料区
		50:
			ParameterList3:=1;                           //取1号吸盘工具
			A00_取放工具();
			IF 取工具完成 THEN
				取工具完成:=FALSE;
				机器人流程:=51;
			END_IF
		51:
			A32_取拍照硅胶板();
			IF 取拍照硅胶板完成 THEN
				取拍照硅胶板完成:=FALSE;
				机器人流程:=52;
			END_IF
		52:
			A65_放废料硅胶板();
			IF 取刮板硅胶板放废料区完成 THEN
				拍照工位允许取硅胶板放废料区:=FALSE;
				取刮板硅胶板放废料区完成:=FALSE;
				FunctionID:=0;

				机器人流程:=0;
			END_IF







//取收集瓶组到暂存工位
		60:
			ParameterList3:=2;            //取2号大夹持工具
			A00_取放工具();
			IF 取工具完成 THEN
				取工具完成:=FALSE;
				机器人流程:=61;
			END_IF
		61:
			A41_取收集瓶组放暂存工位();
			IF 取收集瓶组放暂存工位完成 THEN
				collect_Fetch_Rack_Plate:=0;
				FunctionID:=0;
				机器人流程:=0;
				取收集瓶组放暂存工位完成:=FALSE;
			END_IF







//取收集器组到暂存工位
		70:
			ParameterList3:=2;            //取2号大夹持工具
			A00_取放工具();
			IF 取工具完成 THEN
				取工具完成:=FALSE;
				机器人流程:=71;
			END_IF
		71:
			A40_取收集器组放暂存工位();
			IF 取收集器组放暂存工位完成 THEN
				scrape_Fetch_Rack_Plate:=0;
				FunctionID:=0;
				机器人流程:=0;
				取收集器组放暂存工位完成:=FALSE;
			END_IF





//取收集瓶暂存工位到仓库
		80:
			ParameterList3:=2;            //取2号大夹持工具
			A00_取放工具();
			IF 取工具完成 THEN
				取工具完成:=FALSE;
				机器人流程:=81;
			END_IF
		81:
			A71_取暂存收集瓶放仓库();
			IF 取暂存收集瓶组放仓库完成 THEN
				collect_Old_Plate_Slot:=0;
				FunctionID:=0;
				机器人流程:=0;
				取暂存收集瓶组放仓库完成:=FALSE;
			END_IF		










//取收集器暂存工位到仓库
		90:
			ParameterList3:=2;            //取2号大夹持工具
			A00_取放工具();
			IF 取工具完成 THEN
				取工具完成:=FALSE;
				机器人流程:=91;
			END_IF
		91:
			A70_取暂存收集器组放仓库();
			IF 取暂存收集器组放仓库完成 THEN
				scrape_Old_Plate_Slot:=0;
				FunctionID:=0;
				机器人流程:=0;
				取暂存收集器组放仓库完成:=FALSE;
			END_IF	







//取暂存收集器到刮取位
		100:
			ParameterList3:=3;                           //取3号小夹持工具
			A00_取放工具();
			IF 取工具完成 THEN
				取工具完成:=FALSE;
				机器人流程:=101;
			END_IF	
		101:
			A45_取暂存收集器放刮板位();
			IF 取暂存收集器放刮板位完成 THEN
				scrape_Consume_Slot:=0;
				FunctionID:=0;
				取暂存收集器放刮板位完成:=FALSE;
				机器人流程:=0;
			END_IF








//取刮板拍照收集器到收集工位
		110:
			ParameterList3:=3;                           //取3号小夹持工具
			A00_取放工具();
			IF 取工具完成 THEN
				取工具完成:=FALSE;
				机器人流程:=111;
			END_IF
		111:
			A55_取刮板收集器放到收集工位();
			IF 取刮板收集器放到收集工位完成 THEN
				FunctionID:=0;
				取刮板收集器放到收集工位完成:=FALSE;
				机器人流程:=0;
			END_IF








//取暂存收集瓶到收集工位	
		120:
			ParameterList3:=3;                           //取3号小夹持工具
			A00_取放工具();
			IF 取工具完成 THEN
				取工具完成:=FALSE;
				机器人流程:=121;
			END_IF
		121:
			A50_取暂存收集瓶放收集工位();
			IF 取暂存收集瓶放收集工位完成 THEN
				FunctionID:=0;
				取暂存收集瓶放收集工位完成:=FALSE;
				机器人流程:=0;
			END_IF








//取收集器到暂存工位
		130:
			ParameterList3:=3;                           //取3号小夹持工具
			A00_取放工具();
			IF 取工具完成 THEN
				取工具完成:=FALSE;
				机器人流程:=131;
			END_IF
		131:
			A60_取收集器放暂存工位();
			IF 取收集器放暂存工位完成 THEN
				collect_Powder_Return_Slot:=0;
				收集器组站位符:=FALSE;
				收集工位放收集器完成:=TRUE;
				FunctionID:=0;
				机器人流程:=0;
				取收集器放暂存工位完成:=FALSE;
			END_IF






//取收集瓶到暂存工位
		140:
			ParameterList3:=3;                           //取3号小夹持工具
			A00_取放工具();
			IF 取工具完成 THEN
				取工具完成:=FALSE;
				机器人流程:=141;
			END_IF
		141:
			A65_取收集瓶放暂存工位();
			IF 取收集瓶放暂存工位完成 THEN
				scrape_Consume_Slot:=0;
				收集瓶组站位符:=FALSE;
				FunctionID:=0;
				机器人流程:=0;
				取收集瓶放暂存工位完成:=FALSE;
			END_IF



    END_CASE
END_IF

CASE 取展缸硅胶板step OF
	0:
		地轨轴11YDATE.fAbsTarget:=HMI_地轨轴11Y.position[5];     //地轨去展开位
		地轨轴11YDATE.xMoveAbs:=TRUE;
		IF 地轨轴11YDATE.bAbMoveDone THEN
			地轨轴11YDATE.xMoveAbs:=FALSE;
			取展缸硅胶板step:=10;
		END_IF
	10:
		IF  ParameterList1>0 AND Status=0 THEN
			FunctionID:=5;                                  //取展缸硅胶板
			Execute:=1;
			取展缸硅胶板step:=20;
		END_IF
	20:
		IF RO_ParameterList1>0 AND Status=2 THEN                       //取硅胶板完成
			Execute:=0;
			取展缸硅胶板完成:=TRUE;
			取展缸硅胶板step:=0;
		END_IF
END_CASE

CASE 取收集器放暂存工位step OF
	0:
		地轨轴11YDATE.fAbsTarget:=HMI_地轨轴11Y.position[3];     //地轨去取收集组位置暂存位置
			地轨轴11YDATE.xMoveAbs:=TRUE;
			取收集器放暂存工位step:=5;

	5:
		IF 地轨轴11YDATE.bAbMoveDone  THEN
			地轨轴11YDATE.xMoveAbs:=FALSE;
			FunctionID:=12;  
			ParameterList8:=6;                               //放收集器回暂存工位
			Execute:=1;
			取收集器放暂存工位step:=10;
		END_IF
	10:
		IF RO_ParameterList8=6  THEN                       //放收集器回暂存工位完成
			收集工位机器人到达收集器位置:=TRUE;
			取收集器放暂存工位step:=30;
		END_IF
	30:
		IF 收集工位机器人取收集器放回暂存工位 THEN
			ParameterList8:=7;                               //机器人去取收集器
			ParameterList7:=collect_Powder_Return_Slot;
			收集工位机器人取收集器放回暂存工位:=FALSE;
			取收集器放暂存工位step:=40;
		END_IF
	40:
		IF RO_ParameterList8=7 AND Status=2 THEN                         //到达夹持位置
			Execute:=0;
			取收集器放暂存工位完成:=TRUE;
			取收集器放暂存工位step:=0;
		END_IF
END_CASE

CASE 取工具setp OF
	0:
		IF RO_ParameterList3=ParameterList3 THEN
			取工具完成:=TRUE;
			取工具setp:=0;
		ELSE
			取工具setp:=5;
		END_IF
	5:
		地轨轴11YDATE.fAbsTarget:=HMI_地轨轴11Y.position[4];     //地轨去取工具位置
		地轨轴11YDATE.xMoveAbs:=TRUE;
		IF 地轨轴11YDATE.bAbMoveDone THEN
			地轨轴11YDATE.xMoveAbs:=FALSE;
			FunctionID:=23;                              //取工具ID
			Execute:=1;                                  //机器人启动                        
			取工具setp:=10;
		END_IF
	10:
		IF RO_ParameterList3=ParameterList3 AND Status=2 THEN                               //取工具完成                                   
			Execute:=0;
			取工具完成:=TRUE;
			取工具setp:=0;
		END_IF
END_CASE

CASE 放拍照硅胶板step OF
	0:
		地轨轴11YDATE.fAbsTarget:=HMI_地轨轴11Y.position[2];     //地轨去刮板拍照位
		地轨轴11YDATE.xMoveAbs:=TRUE;
		IF 地轨轴11YDATE.bAbMoveDone AND Status=0 THEN
				地轨轴11YDATE.xMoveAbs:=FALSE;
				FunctionID:=6;                              //放拍照硅胶板
				ParameterList5:=1;                           //放硅胶板到刮板拍照位
				Execute:=1;                                  //机器人启动                        
				放拍照硅胶板step:=10;
		END_IF
	10:
		IF RO_ParameterList5=1 AND Status=2 THEN              //放硅胶板完成
			Execute:=0; 
			ParameterList5:=0;
			拍照工位放硅胶板完成:=TRUE;
			放拍照硅胶板完成:=TRUE;
			放拍照硅胶板step:=0;
		END_IF
END_CASE

CASE 取刮板硅胶板放废料区step OF
	0:
		地轨轴11YDATE.fAbsTarget:=HMI_地轨轴11Y.position[1];     //地轨去上样点样位置
			地轨轴11YDATE.xMoveAbs:=TRUE;
			IF 地轨轴11YDATE.bAbMoveDone THEN
				地轨轴11YDATE.xMoveAbs:=FALSE;
				取刮板硅胶板放废料区step:=5;
            END_IF
	5:
		IF  升降下料伺服允许放料 AND  Status=0 THEN

			FunctionID:=8; 
			ParameterList4:=3;                                     //机器人放到废料区
			Execute:=1; 
			取刮板硅胶板放废料区step:=10;
		END_IF
	10:
		IF RO_ParameterList4=3 AND Status=2  THEN                               //机器人放废料区完成
			Execute:=0; 
			刮板拍照工位站位符:=FALSE;
			升降下料机器人放废料完成:=TRUE;
			取刮板硅胶板放废料区完成:=TRUE;
			取刮板硅胶板放废料区step:=0;
		END_IF
END_CASE

CASE 取收集瓶组放暂存工位step OF
	0:
			地轨轴11YDATE.fAbsTarget:=HMI_地轨轴11Y.position[6];     //地轨去取收集组位置
			地轨轴11YDATE.xMoveAbs:=TRUE;
			取收集瓶组放暂存工位step:=10;
	10:
		IF 地轨轴11YDATE.bAbMoveDone AND Status=0 THEN
				地轨轴11YDATE.xMoveAbs:=FALSE;
				FunctionID:=21;                              //取收集瓶组
				ParameterList6:=collect_Fetch_Rack_Plate+6;       //取收集瓶组坐标
				Execute:=1;                                  //机器人启动                        
				取收集瓶组放暂存工位step:=20;
			END_IF
	20:
		IF RO_ParameterList6=ParameterList6 AND Status=2 THEN             //取收集瓶组完成
			Execute:=0;
			地轨轴11YDATE.fAbsTarget:=HMI_地轨轴11Y.position[3];     //地轨去收集工位
			地轨轴11YDATE.xMoveAbs:=TRUE;
			取收集瓶组放暂存工位step:=30;
		END_IF
	30:
		IF 地轨轴11YDATE.bAbMoveDone AND Status=0 THEN
				地轨轴11YDATE.xMoveAbs:=FALSE;
				FunctionID:=22;                              //放收集瓶组
				ParameterList6:=14;                         //放收集瓶组
				Execute:=1;                                  //机器人启动                        
				取收集瓶组放暂存工位step:=40;
		END_IF
	40:
		IF RO_ParameterList6=14 AND Status=2 THEN                        //放收集瓶完成
			Execute:=0; 
			ParameterList6:=0;
			溶液收集瓶定位自动:=TRUE;
			取收集瓶组放暂存工位完成:=TRUE;
			取收集瓶组放暂存工位step:=0;
		END_IF
END_CASE

CASE 取收集器组放暂存工位step OF
	0:
		地轨轴11YDATE.fAbsTarget:=HMI_地轨轴11Y.position[6];     //地轨去取收集组位置
		地轨轴11YDATE.xMoveAbs:=TRUE;
		取收集器组放暂存工位step:=10;

	10:
		IF 地轨轴11YDATE.bAbMoveDone  AND Status=0 THEN
				地轨轴11YDATE.xMoveAbs:=FALSE;
				FunctionID:=19;                              //取收集器组
				ParameterList6:=scrape_Fetch_Rack_Plate;       //取收集器组坐标
				Execute:=1;                                  //机器人启动                        
				取收集器组放暂存工位step:=20;
			END_IF
	20:
		IF RO_ParameterList6=ParameterList6 AND Status=2 THEN             //取收集器组完成
			Execute:=0;
			地轨轴11YDATE.fAbsTarget:=HMI_地轨轴11Y.position[3];     //地轨去收集
			地轨轴11YDATE.xMoveAbs:=TRUE;
			取收集器组放暂存工位step:=30;
		END_IF
	30:
		IF 地轨轴11YDATE.bAbMoveDone AND Status=0 THEN
				地轨轴11YDATE.xMoveAbs:=FALSE;
				FunctionID:=20;                              //放收集器组
				ParameterList6:=13;                         //取收集器组坐标
				Execute:=1;                                  //机器人启动                        
				取收集器组放暂存工位step:=40;
		END_IF
	40:
		IF RO_ParameterList6=13  AND Status=2 THEN                        //放收集器完成
			Execute:=0; 
			粉末收集器定位自动:=TRUE;
			取收集器组放暂存工位完成:=TRUE;
			取收集器组放暂存工位step:=0;
		END_IF

END_CASE

CASE 放点样硅胶板step OF
	0:	IF  Status=0 THEN
	  		ParameterList4:=0;
			FunctionID:=2;                         //放点样硅胶板
			ParameterList2:=1;                     //机器人放硅胶板
			Execute:=1;
			放点样硅胶板step:=10;
	  	END_IF

	10:
		IF RO_ParameterList2=1 AND Status=2 THEN         //机器人放硅胶板完成
			上样点样放硅胶板完成:=TRUE;
			Execute:=0;
			放点样硅胶板完成:=TRUE;
			放点样硅胶板step:=0;
		END_IF
END_CASE

CASE 取刮板收集器放到收集工位step OF
	0:
		地轨轴11YDATE.fAbsTarget:=HMI_地轨轴11Y.position[2];     //地轨去取收集组位置暂存位置
			地轨轴11YDATE.xMoveAbs:=TRUE;
			取刮板收集器放到收集工位step:=1;
	1:
		IF 地轨轴11YDATE.bAbMoveDone AND 拍照工位允许取收集器 AND  Status=0 THEN
			地轨轴11YDATE.xMoveAbs:=FALSE;
			拍照工位机器人退出工位完成:=FALSE;
			FunctionID:=11;
			Execute:=1;
			ParameterList5:=4;                          //机器人去夹持工位
			取刮板收集器放到收集工位step:=10;
		END_IF
	10:
		IF RO_ParameterList5=4 THEN
			拍照工位机器人到达收集器夹持位:=TRUE;
			取刮板收集器放到收集工位step:=20;
		END_IF
	20:
		IF 拍照工位机器人退出 THEN

			拍照工位机器人到达收集器夹持位:=FALSE;
			ParameterList5:=5;                          //机器人退出工位
			取刮板收集器放到收集工位step:=30;
		END_IF
	30:
		IF RO_ParameterList5=5 THEN
			拍照工位机器人退出完成:=TRUE;
			Execute:=0;
			地轨轴11YDATE.fAbsTarget:=HMI_地轨轴11Y.position[3];     //地轨去收集工位
			地轨轴11YDATE.xMoveAbs:=TRUE;
			取刮板收集器放到收集工位step:=40;
		END_IF
	40:
		IF 地轨轴11YDATE.bAbMoveDone THEN
			地轨轴11YDATE.xMoveAbs:=FALSE;                     
			取刮板收集器放到收集工位step:=50;
		END_IF
	50:
		IF 收集工位允许放收集器 AND  Status=0 THEN
			FunctionID:=12;                             //放收集工位收集器
			ParameterList8:=1;                         //机器人放收集器到夹持工位
			Execute:=1;
			取刮板收集器放到收集工位step:=60;
		END_IF
	60:
		IF RO_ParameterList8=1 THEN

			收集工位放收集器到工位:=TRUE;
			取刮板收集器放到收集工位step:=70;
		END_IF
	70:
		IF 收集工位允许机器人退出工位 THEN
			ParameterList8:=2;                     //机器人退出工位
			取刮板收集器放到收集工位step:=80;
		END_IF
	80:
		IF RO_ParameterList8=2 AND Status=2 THEN                //机器人退出工位完成
			Execute:=0;
			收集工位机器人退出完成:=TRUE;
			收集工位放收集器到工位:=FALSE;
			取刮板收集器放到收集工位完成:=TRUE;
			取刮板收集器放到收集工位step:=0;
		END_IF
END_CASE

CASE 取暂存收集器放刮板位step OF
	0:
		IF RO_ParameterList3=3 THEN
			ParameterList3:=0;
			Execute:=0;
			地轨轴11YDATE.fAbsTarget:=HMI_地轨轴11Y.position[2];     //地轨去刮板拍照位
			地轨轴11YDATE.xMoveAbs:=TRUE;
			取暂存收集器放刮板位step:=10;
		END_IF
	10:
		IF 地轨轴11YDATE.bAbMoveDone THEN
			地轨轴11YDATE.xMoveAbs:=FALSE;                     
			取暂存收集器放刮板位step:=20;
		END_IF
	20:
		IF 拍照工位允许放收集器 AND Status=0 THEN
			FunctionID:=9;                              //取暂存收集器
			ParameterList7:=scrape_Consume_Slot;           //取收集器
			Execute:=1;
			取暂存收集器放刮板位step:=30;
		END_IF
	30:
		IF RO_ParameterList7=ParameterList7  THEN                   //取收集器完成
			Execute:=0;
			取暂存收集器放刮板位step:=40;
		END_IF
	40:
		IF Status=0 THEN
			FunctionID:=10;                             //放收集器
			ParameterList5:=2;                         //机器人放收集器到夹持工位
			Execute:=1;
			取暂存收集器放刮板位step:=45;
		END_IF
	45:
		IF RO_ParameterList5=2 THEN
			拍照工位机器人到达夹持位:=TRUE;
			取暂存收集器放刮板位step:=50;
		END_IF
	50:
		IF 拍照工位机器人退出工位 THEN
			ParameterList5:=3;                         //机器人退出工位
			拍照工位机器人到达夹持位:=FALSE;
			取暂存收集器放刮板位step:=60;
		END_IF
	60:
		IF RO_ParameterList5=3 AND Status=2 THEN                    //机器人退出工位完成
			Execute:=0;
			拍照工位机器人退出工位完成:=TRUE;
			取暂存收集器放刮板位完成:=TRUE;
			取暂存收集器放刮板位step:=0;
		END_IF	




END_CASE

