CASE 取升降硅胶板step OF
		0:
			地轨轴11YDATE.fAbsTarget:=HMI_地轨轴11Y.position[1];     //地轨去上样点样位置
			地轨轴11YDATE.xMoveAbs:=TRUE;
			IF 地轨轴11YDATE.bAbMoveDone THEN
				地轨轴11YDATE.xMoveAbs:=FALSE; 
				IF 升降上料伺服允许取料 AND Status=0 THEN
					FunctionID:=1;                              //取升降硅胶板ID
					ParameterList4:=1;                           //去升降机构位置
					Execute:=1;                                  //机器人启动 
					取升降硅胶板step:=10;
				END_IF
			END_IF

		10:
			IF RO_ParameterList4=1 THEN                   //机器人到位
				升降上料机器人已吸住物料:=TRUE;
				取升降硅胶板step:=15;
			END_IF
		15:
			IF 升降上料伺服下降完成  THEN
				ParameterList4:=2;                        //机器人取物料
				取升降硅胶板step:=20;
			END_IF

		20:
			IF RO_ParameterList4=2 AND Status=2 THEN                //机器人取物料完成
				ParameterList4:=0;
				Execute:=0;
				升降上料机器人取料完成:=TRUE;
				取升降硅胶板完成:=TRUE;
				取升降硅胶板step:=0;
			END_IF
END_CASE

