CASE 取拍照硅胶完step OF
	0:
		地轨轴11YDATE.fAbsTarget:=HMI_地轨轴11Y.position[2];     //地轨去刮板拍照位
		地轨轴11YDATE.xMoveAbs:=TRUE;
		IF 地轨轴11YDATE.bAbMoveDone THEN
				地轨轴11YDATE.xMoveAbs:=FALSE;
				取拍照硅胶完step:=5;
		END_IF
	5:		
		IF (拍照工位允许取硅胶板去展开 OR 拍照工位允许取硅胶板放废料区) AND Status=0 THEN    
			FunctionID:=6;                              
			ParameterList5:=6;                           //机器人取硅胶板
			Execute:=1;             
			拍照工位允许取硅胶板去展开 := FALSE;
			取拍照硅胶完step:=10;
		END_IF
	10:
		IF RO_ParameterList5=6 AND Status=2 THEN
			Execute:=0;
			ParameterList6:=0;
			取拍照硅胶板完成:=TRUE;
			取拍照硅胶完step:=0;
		IF 拍照工位允许取硅胶板放废料区 THEN
			拍照工位机器人取硅胶板完成 := TRUE;
		END_IF
		END_IF
END_CASE
